import json
from pathlib import Path
ROOT=Path(__file__).parent
blocks=[]
def s(title,text,latex,alt): return dict(title=title,text=text,latex=latex,alt=alt)
def b(id,lesson,part,title,intro,steps,summary,scene,replace=None):
    blocks.append(dict(id=id,lesson=lesson,part=part,title='Worked example: '+title,intro=intro,steps=steps,summary=summary,scene=scene,replace=replace))

b('01-charge',1,1,'Count transferred electrons',
'Two initially neutral objects are rubbed together. Object A gains 2.0 × 10¹² electrons from object B. Find each object’s net charge. Use e = 1.60 × 10⁻¹⁹ C.',[
s('Identify what moved','Electrons move from B to A. Protons remain in the material. A gains negative charge, while B loses the same amount of negative charge.',r'q_{\mathrm{electron}}=-e=-1.60\times10^{-19}\,\mathrm{C}','Electrons travel from object B to object A; each begins neutral.'),
s('Calculate the charge magnitude','Multiply the number of transferred electrons by the magnitude of one electron’s charge. Add the powers of ten when multiplying.',r'|q|=Ne=(2.0\times10^{12})(1.60\times10^{-19})=3.2\times10^{-7}\,\mathrm{C}','Object A has an excess of electrons and object B has an equal deficit.'),
s('Assign signs and convert units','A has gained electrons, so its net charge is negative. B is positive. A microcoulomb is one millionth of a coulomb.',r'q_A=-0.32\,\mu\mathrm{C},\quad q_B=+0.32\,\mu\mathrm{C}\\1\,\mu\mathrm{C}=10^{-6}\,\mathrm{C}','A is marked negative and B positive, with equal charge magnitudes.'),
s('Check charge conservation','The two-object system began with zero net charge. Electron transfer separates charge but does not create a net charge for the isolated system.',r'q_{\mathrm{total}}=(-3.2+3.2)\times10^{-7}=0\,\mathrm{C}','A boundary encloses both charged objects, emphasizing the isolated system.')],
'A ends at −0.32 μC and B at +0.32 μC. Charge signs track electron gain or loss, and the system’s total charge remains zero.','charge')

b('02-coulomb',1,2,'Calculate and scale an electric force',
'Two point charges, +2.0 μC and −3.0 μC, are 0.50 m apart in air. Find the force magnitude and direction. Use k = 8.99 × 10⁹ N·m²/C².',[
s('Convert and predict the direction','Convert both charges to coulombs before substituting. Opposite charges attract; each force points toward the other charge.',r'q_1=+2.0\times10^{-6}\,\mathrm{C},\quad q_2=-3.0\times10^{-6}\,\mathrm{C}','Positive and negative point charges are separated by 0.50 m; inward arrows show attraction.'),
s('Substitute magnitudes','Coulomb’s law gives the force magnitude when the absolute value of the charge product is used. Square the separation, not either charge.',r'F=k\frac{|q_1q_2|}{r^2}=\frac{(8.99\times10^9)(2.0\times10^{-6})(3.0\times10^{-6})}{(0.50)^2}','The two charges and center-to-center separation are highlighted.'),
s('Calculate and interpret','Carry the exponent from both microcoulomb conversions. Each charge experiences a force of the same magnitude, even though their charge amounts differ.',r'F=0.21576\,\mathrm{N}\approx0.216\,\mathrm{N}\\\vec F_{1\leftarrow2}=-\vec F_{2\leftarrow1}','Equal-length force arrows point inward toward the opposite charge.'),
s('Test a simultaneous change','If both charge magnitudes double and separation halves, combine all three factors. The force increases sixteenfold, not eightfold.',r'\frac{F_{\mathrm{new}}}{F}=\frac{(2)(2)}{(1/2)^2}=16\\F_{\mathrm{new}}\approx3.45\,\mathrm{N}','Comparison panels show doubled charge magnitudes and half the original separation.')],
'The original force is about 0.216 N and attractive. Unit conversion and the squared distance are essential. The combined change produces a force 16 times larger.','coulomb','Finding Electric Force')

b('03-net-force',1,3,'Add forces on the middle charge',
'Q₁ = +3.0 μC lies 0.40 m left of Q₂ = −2.0 μC. Q₃ = +5.0 μC lies 0.50 m right of Q₂. Find the net force on Q₂, using k = 8.99 × 10⁹ N·m²/C².',[
s('Draw only forces on the target','Both positive charges attract Q₂. The left charge pulls left; the right charge pulls right. Choose right as positive. Use distances measured from Q₂.',r'r_{12}=0.40\,\mathrm{m},\quad r_{23}=0.50\,\mathrm{m}\\F_{12}<0,\quad F_{32}>0','Three charges lie in a line; opposing arrows are drawn on the negative middle charge.'),
s('Find the leftward force','Calculate the magnitude from Q₁, then assign a negative sign because it points left. The labels identify the force source and target.',r'|F_{12}|=\frac{(8.99\times10^9)(3.0\times10^{-6})(2.0\times10^{-6})}{0.40^2}=0.337125\,\mathrm{N}\\F_{12}=-0.337125\,\mathrm{N}','The left pair and the leftward force on Q₂ are highlighted.'),
s('Find the rightward force','Calculate the force from Q₃ separately. Its larger charge outweighs its greater distance in this example.',r'F_{32}=+\frac{(8.99\times10^9)(5.0\times10^{-6})(2.0\times10^{-6})}{0.50^2}=+0.359600\,\mathrm{N}','The right pair and the rightward force on Q₂ are highlighted.'),
s('Add signed forces and check','The opposing forces nearly cancel. Add their signed values rather than their magnitudes. The positive result points right.',r'F_{\mathrm{net}}=-0.337125+0.359600=+0.022475\,\mathrm{N}\\F_{\mathrm{net}}\approx0.0225\,\mathrm{N}\text{ right}','Nearly equal opposing arrows leave a small net-force arrow pointing right.')],
'The net force is about 0.0225 N to the right. It is much smaller than either individual force because they almost cancel.','net','The Problem')

b('04-force-comparison',1,3,'Compare electric force with gravity',
'Compare electric attraction and gravitational attraction between a proton and electron at the same separation. Use e = 1.60 × 10⁻¹⁹ C, mₚ = 1.67 × 10⁻²⁷ kg, mₑ = 9.11 × 10⁻³¹ kg, k = 8.99 × 10⁹ and G = 6.67 × 10⁻¹¹ in SI units.',[
s('Write both force models','Both forces attract this pair, and both depend on inverse separation squared. Compare their magnitudes using a ratio.',r'F_E=\frac{ke^2}{r^2},\qquad F_G=\frac{Gm_pm_e}{r^2}','A proton and electron attract each other; electric and gravitational interactions share the same separation.'),
s('Cancel the common distance','The separation cancels because both forces are evaluated between the same particles at the same distance.',r'\frac{F_E}{F_G}=\frac{ke^2/r^2}{Gm_pm_e/r^2}=\frac{ke^2}{Gm_pm_e}','The same separation bracket is emphasized for the two interactions.'),
s('Substitute in scientific notation','Keep the mass and charge exponents intact. The ratio has no units because it compares two forces.',r'\frac{F_E}{F_G}=\frac{(8.99\times10^9)(1.60\times10^{-19})^2}{(6.67\times10^{-11})(1.67\times10^{-27})(9.11\times10^{-31})}\approx2.27\times10^{39}','Electric and gravitational attraction act between the same particles; arrows show direction only, not relative magnitude.'),
s('Interpret the limits','Electric attraction dominates for this particle pair. This does not mean it always dominates for everyday objects, which can contain nearly balanced positive and negative charges.',r'\frac{F_E(2r)}{F_G(2r)}=\frac{F_E(r)}{F_G(r)}','A neutral object contains balanced positive and negative charge, contrasting with two isolated charged particles.')],
'Electric attraction is about 2.27 × 10³⁹ times stronger for a proton-electron pair. The ratio is independent of their common separation.','comparison')

b('05-field-force',2,1,'Find a field and a charge’s force',
'A +4.0 μC source charge is 0.30 m left of point P. A small −2.0 nC charge is placed at P. Calculate the electric field at P and the force on that negative charge.',[
s('Separate source from test charge','The source charge determines the field. At P, the field points right, away from the positive source. A negative charge feels a force opposite to the field.',r'Q=4.0\times10^{-6}\,\mathrm{C},\quad q=-2.0\times10^{-9}\,\mathrm{C}','A positive source sits left of P; field points right and negative-charge force points left.'),
s('Calculate field strength','Use the source charge and its distance from P. Field strength is force per unit positive test charge.',r'E=\frac{k|Q|}{r^2}=\frac{(8.99\times10^9)(4.0\times10^{-6})}{0.30^2}=4.00\times10^5\,\mathrm{N/C}','Radial arrows leave the source; the rightward field at P is highlighted.'),
s('Calculate the signed force','Take right as positive and multiply by the signed charge. A negative result reverses direction relative to the field.',r'F_x=qE_x=(-2.0\times10^{-9})(3.996\times10^5)=-7.99\times10^{-4}\,\mathrm{N}','The negative test charge has a leftward force arrow, opposite the field arrow.'),
s('Check what changes with distance','At twice the distance the source field is one quarter as strong, so the same test charge experiences one quarter the force. Force determines acceleration, not necessarily existing velocity.',r'E(2r)=\frac{E(r)}4\approx9.99\times10^4\,\mathrm{N/C}\\|F(2r)|\approx2.00\times10^{-4}\,\mathrm{N}','The test point moves twice as far from the source, with a shorter field arrow.')],
'The field is 4.00 × 10⁵ N/C rightward. The negative charge experiences about 7.99 × 10⁻⁴ N leftward.','field')

b('06-potential-energy',2,2,'Connect voltage, field, and work',
'Parallel plates are 0.040 m apart. The left plate is at 120 V and the right plate at 0 V. A +2.0 μC charge moves from right to left at constant speed. Neglect edge effects and other forces.',[
s('Determine field direction and size','Electric field points from higher to lower potential, so it points right. Use the voltage difference magnitude divided by plate separation for a uniform field.',r'E=\frac{|\Delta V|}{d}=\frac{120}{0.040}=3.00\times10^3\,\mathrm{N/C}','Parallel plates at 120 V and 0 V have a uniform field directed right.'),
s('Find the electric force','The positive charge feels a rightward electric force. To move it left at constant speed, an external agent supplies an equal leftward force.',r'F_E=qE=(2.0\times10^{-6})(3.00\times10^3)=6.0\times10^{-3}\,\mathrm{N}','The charge moves left while electric force points right and external force points left.'),
s('Calculate potential-energy change','Use final minus initial potential. The positive charge moves to higher potential and gains electric potential energy.',r'\Delta V=120-0=+120\,\mathrm{V}\\\Delta U=q\Delta V=(2.0\times10^{-6})(120)=+2.4\times10^{-4}\,\mathrm{J}','A positive charge moves left toward the higher-potential plate, against the rightward electric force.'),
s('Distinguish the two kinds of work','Electric work is negative because electric force opposes displacement. At constant speed, the external agent supplies the positive energy increase.',r'W_E=-\Delta U=-2.4\times10^{-4}\,\mathrm{J}\\W_{\mathrm{ext}}=+\Delta U=+2.4\times10^{-4}\,\mathrm{J}\\W_{\mathrm{net}}=0=\Delta K','Opposing forces act during leftward displacement; kinetic energy remains unchanged.')],
'The external agent supplies 2.4 × 10⁻⁴ J, stored as electric potential energy. The electric field does the same magnitude of negative work.','plates')

b('07-current',3,1,'Turn charge flow into current',
'A charge magnitude of 18 C passes a cross-section of a metal wire in 12 s. Calculate average current and the number of electrons that cross. Use e = 1.60 × 10⁻¹⁹ C.',[
s('Identify the measured interval','Current describes charge crossing a section per unit time. It does not mean the wire is gaining that much net charge.',r'\Delta Q=18\,\mathrm{C},\qquad\Delta t=12\,\mathrm{s}','A marked cross-section counts electrons moving through a wire during a measured interval.'),
s('Calculate average current','Divide charge magnitude by elapsed time. One ampere is one coulomb per second.',r'I_{\mathrm{avg}}=\frac{\Delta Q}{\Delta t}=\frac{18}{12}=1.5\,\mathrm{A}','Electron flow crosses the counting plane; a meter shows the current.'),
s('Count the electron carriers','Divide the total charge magnitude by one electron’s charge magnitude. This is a count, not a charge in coulombs.',r'N=\frac{\Delta Q}{e}=\frac{18}{1.60\times10^{-19}}=1.125\times10^{20}\text{ electrons}','Many electron carriers pass the section; the drawing represents a large population.'),
s('Check direction and a new interval','Conventional current points opposite to electron drift in a metal. If 1.5 A continues for another 4.0 s, 6.0 C crosses the section.',r'\Delta Q=I\Delta t=(1.5)(4.0)=6.0\,\mathrm{C}','Opposing arrows label conventional current and electron drift in the same wire.')],
'The average current is 1.5 A. About 1.1 × 10²⁰ electrons cross in 12 s, while conventional current points opposite to their drift.','current')

b('08-ohms-law',3,2,'Find an unknown resistance',
'A resistor is connected to a 9.0 V supply. An ammeter reads 150 mA. Calculate its resistance and predict current at 12 V if its temperature and resistance stay constant.',[
s('Read the meters and convert','The ammeter is in series with the resistor; the voltmeter measures across it. Convert milliamperes to amperes before calculating resistance.',r'I=150\,\mathrm{mA}=0.150\,\mathrm{A},\quad V=9.0\,\mathrm{V}','Ammeter lies in series and voltmeter is connected across the resistor.'),
s('Rearrange before substituting','Divide both sides of V = IR by current to isolate resistance. Resistance is measured in ohms.',r'V=IR\quad\Rightarrow\quad R=\frac VI=\frac{9.0}{0.150}=60\,\Omega','The resistor and voltage across it are highlighted in the circuit.'),
s('Predict a new current','For this ohmic resistor at constant temperature, use the same resistance at the new voltage.',r'I_{\mathrm{new}}=\frac{V_{\mathrm{new}}}{R}=\frac{12}{60}=0.20\,\mathrm{A}','The same resistor is connected to a supply now labeled 12 V.'),
s('Check using the original values','Substituting the original current and calculated resistance must recover the measured voltage. A hotter filament or other non-ohmic device may not keep constant resistance.',r'IR=(0.150)(60)=9.0\,\mathrm{V}\\\frac{0.20}{0.150}=\frac{12}{9.0}','The original circuit and its consistent voltage-current readings are shown together.')],
'The resistance is 60 Ω. At 12 V it draws 0.20 A under the constant-resistance assumption.','ohm','Understanding Ohm’s Law in Circuits')

b('09-vi-graph',3,2,'Read resistance from a graph',
'A device’s voltage-versus-current graph has voltage on the vertical axis. It includes (0.10 A, 2.0 V), (0.20 A, 4.0 V), and (0.30 A, 6.0 V). Determine its resistance and whether these data support an ohmic model.',[
s('Check the axes first','For voltage plotted vertically against current horizontally, slope has units of volts per ampere. Reversing the axes would give the reciprocal relationship.',r'\text{slope}=\frac{\Delta V}{\Delta I}\quad[\mathrm{V/A}=\Omega]','A straight voltage-versus-current graph shows all three measured points.'),
s('Use two well-separated points','Find differences in voltage and current between the outer points. Using differences is the general slope method.',r'R=\frac{6.0-2.0}{0.30-0.10}=\frac{4.0}{0.20}=20\,\Omega','A slope triangle spans the outer two points on the graph.'),
s('Check proportionality','Each measured pair has the same V/I ratio, and the straight line passes through the origin. These results support constant resistance over the tested range.',r'\frac{2.0}{0.10}=\frac{4.0}{0.20}=\frac{6.0}{0.30}=20\,\Omega','The straight line through the origin passes through all measured points.'),
s('Recognize a limit of the model','Suppose a later 8.0 V reading gives only 0.32 A. The ratio is then 25 Ω, indicating changed resistance. Heating is one possible explanation, so do not extend the original line automatically.',r'R_{\mathrm{later}}=\frac{8.0}{0.32}=25\,\Omega\ne20\,\Omega','A later measurement lies above the extension of the original straight voltage-current line.')],
'The initial data give 20 Ω and support an ohmic model over that range. Always identify the axes and check whether resistance remains constant.','graph','Introduction to Using Ohm’s Law in Real Circuits')

b('10-series',3,3,'Solve a series circuit',
'An ideal 12 V battery supplies 4.0 Ω and 8.0 Ω resistors in series. Find total resistance, current, and the voltage across each resistor. Treat wires as having negligible resistance.',[
s('Identify the single path','The same steady current passes through both resistors. Current is not used up by the first resistor.',r'R_{\mathrm{eq}}=R_1+R_2=4.0+8.0=12\,\Omega','One closed loop contains a battery and two series resistors.'),
s('Find current from the whole circuit','Use the supply voltage and equivalent resistance. This current applies everywhere in the series path.',r'I=\frac{V}{R_{\mathrm{eq}}}=\frac{12}{12}=1.0\,\mathrm{A}','Equal current arrows appear before, between, and after the resistors.'),
s('Calculate each voltage drop','Multiply the common current by each resistance. The higher resistance has the larger voltage drop.',r'V_1=IR_1=(1.0)(4.0)=4.0\,\mathrm{V}\\V_2=IR_2=(1.0)(8.0)=8.0\,\mathrm{V}','Voltage brackets span each resistor separately.'),
s('Check the loop and a failure','The voltage drops add to the battery voltage. If either resistor connection opens, the only conducting path is broken and steady current stops in both.',r'V_1+V_2=4.0+8.0=12\,\mathrm{V}\\I_{\mathrm{open}}=0\,\mathrm{A}','A gap in the single path illustrates an open series circuit.')],
'The equivalent resistance is 12 Ω and current is 1.0 A. The voltage drops are 4.0 V and 8.0 V, adding to the 12 V supply.','series')

b('11-parallel',3,3,'Solve a parallel circuit',
'An ideal 12 V supply feeds separate 6.0 Ω and 12 Ω branches. Find branch currents, total current, and equivalent resistance, then predict what happens if the 6.0 Ω branch opens.',[
s('Identify the common voltage','Both branches connect across the same two supply nodes, so each has the full 12 V potential difference.',r'V_1=V_2=V_{\mathrm{supply}}=12\,\mathrm{V}','Two resistor branches connect across the same supply rails.'),
s('Calculate branch currents','Use Ohm’s law separately for each branch. Lower resistance draws more current at the same voltage.',r'I_1=\frac{12}{6.0}=2.0\,\mathrm{A},\qquad I_2=\frac{12}{12}=1.0\,\mathrm{A}','Branch arrows indicate a larger current through the 6 Ω branch.'),
s('Add current and find resistance','At the junction, total current equals the sum of branch currents. Equivalent resistance is lower than the smallest individual branch resistance.',r'I_{\mathrm{total}}=2.0+1.0=3.0\,\mathrm{A}\\R_{\mathrm{eq}}=\frac{12}{3.0}=4.0\,\Omega','Current splits at one junction and recombines at the other.'),
s('Test a branch failure','Opening the 6.0 Ω branch leaves the other branch connected. Its current remains 1.0 A for an ideal fixed-voltage supply; total current falls.',r'I_1=0,\quad I_2=1.0\,\mathrm{A}\\I_{\mathrm{total}}=1.0\,\mathrm{A},\quad R_{\mathrm{eq}}=12\,\Omega','One branch is open while the other still forms a closed path.')],
'The branch currents are 2.0 A and 1.0 A. Total current is 3.0 A and equivalent resistance is 4.0 Ω. A failed branch can leave the other operating.','parallel')

b('12-power',3,3,'Calculate circuit energy use',
'A lamp operates at 12 V and draws 0.50 A for 5.0 minutes. Find electrical power and energy transferred. Then compare two identical 24 Ω resistor-model lamps in series and parallel across the same supply.',[
s('Calculate energy transfer per second','Power is voltage times current. A watt is one joule transferred per second.',r'P=VI=(12)(0.50)=6.0\,\mathrm{W}','Electrical energy enters a lamp and transfers into light and thermal energy.'),
s('Convert the operating time','Use seconds when multiplying watts by time to obtain joules. Five minutes is not five seconds.',r't=(5.0\,\mathrm{min})(60\,\mathrm{s/min})=300\,\mathrm{s}','A clock beside the lamp marks a five-minute operating interval.'),
s('Calculate the energy transfer','Multiply power by duration. Energy is transferred through the circuit; charge is not consumed by the lamp.',r'E=Pt=(6.0)(300)=1800\,\mathrm{J}=1.8\,\mathrm{kJ}','An energy-transfer diagram links electrical input with light and thermal output.'),
s('Compare arrangements using power','Assume each lamp keeps 24 Ω resistance. In series each gets 6 V; in parallel each gets 12 V. Real filament resistance changes with temperature, so these are model predictions.',r'P_{\mathrm{each,series}}=\frac{6^2}{24}=1.5\,\mathrm{W}\\P_{\mathrm{each,parallel}}=\frac{12^2}{24}=6.0\,\mathrm{W}','Two identical lamps are compared in series and parallel arrangements.')],
'The lamp transfers 1.8 kJ in five minutes. In the fixed-resistance comparison, each parallel lamp receives four times the power of each series lamp.','power')

b('13-electromagnet-data',4,3,'Analyze repeated electromagnet trials',
'At 0.50 A an electromagnet lifts 9, 10, and 11 clips in three trials. At 1.00 A it lifts 18, 20, and 19. Coil turns, core, and the pickup method are held constant. What conclusion is supported?',[
s('Identify the fair comparison','Current is the independent variable and clip count is the response. Keeping the other conditions fixed makes the comparison more informative.',r'\frac{I_2}{I_1}=\frac{1.00}{0.50}=2.00','The same coil and core are tested at two currents with other conditions unchanged.'),
s('Average the repeated trials','Calculate a mean for each current rather than choosing only the most favorable observation.',r'\bar n_1=\frac{9+10+11}{3}=10\text{ clips}\\\bar n_2=\frac{18+20+19}{3}=19\text{ clips}','Two sets of three trial points are grouped by current.'),
s('Quantify the change','Doubling current increased the mean clip count by 90%, from 10 to 19. The clip count did not exactly double.',r'\%\text{ increase}=\frac{19-10}{10}\times100\%=90\%','Mean clip-count bars compare 10 clips with 19 clips.'),
s('Make a bounded claim','Higher current increased mean lifting capacity under these conditions. Clip count is a performance measure, not a direct magnetic-field reading. The ranges do not overlap, but more current levels would test the trend.',r'\text{Trial ranges: }9\text{–}11\text{ and }18\text{–}20\text{ clips}','The trial ranges and means are displayed without implying a universal straight-line law.')],
'The evidence supports increased lifting capacity when current rises from 0.50 A to 1.00 A. It does not establish exact proportionality for every current.','data')

b('14-design-value',4,3,'Choose the best-value electromagnet',
'Practice designs give: A lifts 30 clips at cost 10 units; B lifts 42 at cost 12; C lifts 54 at cost 20. The budget is 15 units. Choose the feasible design with the greatest clips per cost, and compare it with A.',[
s('Apply the design constraint first','A design outside the budget cannot win this challenge, even if it lifts the most clips. C exceeds the budget.',r'10\le15,\quad12\le15,\quad20>15','Three design cards show lifting counts and costs; the over-budget design is marked.'),
s('Calculate comparable ratios','Divide clips lifted by cost for each feasible design. A higher ratio gives more lifting capacity per unit of cost.',r'S_A=\frac{30}{10}=3.00\text{ clips/unit}\\S_B=\frac{42}{12}=3.50\text{ clips/unit}','Feasible designs A and B are compared using identical ratio scales.'),
s('Find percentage improvement','Compare the new score with the baseline score, not the clip counts alone. Keep unrounded ratios in the calculation, then round the final percentage.',r'\%\text{ improvement}=\left(\frac{S_B}{S_A}-1\right)100\%=\left(\frac{3.50}{3.00}-1\right)100\%\approx16.7\%','Ratio bars show B above the baseline A.'),
s('Justify the selection','B is within budget and has the larger feasible ratio. The strongest design C is not the best choice for this constrained task.',r'S_C=\frac{54}{20}=2.70\text{ clips/unit}\\S_B>S_A>S_C','B is selected with its cost and lifting capacity visible, while C remains over budget.')],
'Choose B: 3.50 clips per cost unit, about 16.7% better value than A. The application lab uses its own measured values and additional wire limits.','value')

b('15-induction',5,1,'Calculate an induced voltage',
'A 100-turn coil has area 0.020 m² per turn. A uniform magnetic field perpendicular to the coil grows from 0.10 T to 0.30 T in 0.50 s. Find average induced EMF. The complete circuit has resistance 10 Ω.',[
s('Calculate flux change per turn','Magnetic flux is field times area when the field is perpendicular to the coil. The given area is for one turn, so do not multiply by the turn count yet.',r'\Delta\Phi=A\Delta B=(0.020)(0.30-0.10)=0.0040\,\mathrm{Wb}','A coil faces a field directed into the page; denser crosses represent a stronger field.'),
s('Apply Faraday’s law','Average EMF magnitude equals the turn count times flux change per turn divided by the elapsed time.',r'|\mathcal E_{\mathrm{avg}}|=N\frac{|\Delta\Phi|}{\Delta t}=100\frac{0.0040}{0.50}=0.80\,\mathrm{V}','The same field change passes through all turns of the coil.'),
s('Use Lenz’s law for direction','An increasing field into the page induces a field out of the page. The right-hand rule gives counterclockwise current as viewed here. For negligible self-inductance, divide EMF by total resistance.',r'I_{\mathrm{avg}}=\frac{|\mathcal E_{\mathrm{avg}}|}{R}=\frac{0.80}{10}=0.080\,\mathrm{A}','Counterclockwise current creates an outward field opposing the increase into the page.'),
s('Test the rate of change','The same flux change in half the time produces twice the average EMF. Once the field becomes steady, induced EMF from this changing external field is zero.',r'|\mathcal E|_{0.25\,\mathrm{s}}=1.60\,\mathrm{V}\\\Delta\Phi=0\quad\Rightarrow\quad\mathcal E=0','A changing-field interval is contrasted with a steady-field interval.')],
'Average induced EMF is 0.80 V and the resistive-circuit current is 0.080 A. Induced current opposes the change in flux, not necessarily the existing field.','induction')

b('16-efficiency',5,2,'Track energy through a generator and motor',
'A generator receives 200 J of mechanical energy and supplies 150 J electrically. That electrical energy powers a motor with 60% efficiency. Find useful mechanical output and the efficiency of the complete chain.',[
s('Define the generator’s input and output','Generator efficiency compares useful electrical output with mechanical input. Both energies refer to the same interval.',r'\eta_G=\frac{150}{200}\times100\%=75\%','A generator receives mechanical input and supplies electrical output plus a loss branch.'),
s('Calculate the motor output','The motor receives the generator’s 150 J electrical output. Multiply by efficiency written as a decimal.',r'E_{\mathrm{useful}}=\eta_M E_{\mathrm{in,M}}=(0.60)(150)=90\,\mathrm{J}','The electrical output feeds a motor that produces useful mechanical energy.'),
s('Calculate the whole-chain efficiency','Use the original 200 J input as the denominator. Multiplying the component efficiencies gives the same result; adding their percentages does not.',r'\eta_{\mathrm{chain}}=\frac{90}{200}=0.45=45\%\\\eta_G\eta_M=(0.75)(0.60)=0.45','The whole generator-motor chain is enclosed by one system boundary.'),
s('Account for all energy','The generator transfers 50 J and the motor 60 J into less useful forms such as thermal energy and sound. Energy is conserved even though useful output decreases.',r'E_{\mathrm{loss,G}}=200-150=50\,\mathrm{J}\\E_{\mathrm{loss,M}}=150-90=60\,\mathrm{J}\\90+50+60=200\,\mathrm{J}','Useful output and both loss branches account for the entire original energy input.')],
'Useful mechanical output is 90 J and whole-chain efficiency is 45%. The remaining 110 J is transferred into less useful forms, not destroyed.','efficiency')

(ROOT/'process-blocks.json').write_text(json.dumps(blocks,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(blocks)} blocks; {sum(len(b["steps"]) for b in blocks)} instructional steps')
